using System;
using System.Collections.Generic;
using System.IO;
using ClosedXML.Excel;
using ExpenseHub.Api.Reports;
using ExpenseHub.Core.Contracts.Responses;
using ExpenseHub.Core.Reports;
using Microsoft.VisualStudio.TestTools.UnitTesting;

namespace ExpenseHub.UnitTests.Reports;

/// <summary>Opens the generated bytes as a real workbook and compares every cell with the persisted result.</summary>
[TestClass]
public sealed class ReportWorkbookTests
{
    private static readonly Guid _id = new("8d1f3c0e-9b7a-4a51-bc0e-3f0d5e2a1b44");

    /// <summary>The file is a valid .xlsx (ZIP container) whose metadata and numeric cells mirror the result.</summary>
    [TestMethod]
    public void WorkbookMirrorsPersistedResult()
    {
        byte[] bytes = ReportWorkbook.Create(Completed(new List<ReportStatusTotal>
        {
            new("Draft", 0, 0m),
            new("Submitted", 0, 0m),
            new("Approved", 2, 150.00m),
            new("Rejected", 0, 0m),
            new("Paid", 1, 25.00m),
        }, totalCount: 3, totalAmount: 175.00m));
        Assert.AreEqual((byte)'P', bytes[0]);
        Assert.AreEqual((byte)'K', bytes[1]);

        using var workbook = new XLWorkbook(new MemoryStream(bytes));
        IXLWorksheet sheet = workbook.Worksheet("Report");
        Assert.AreEqual(_id.ToString(), sheet.Cell(2, 2).GetString());
        Assert.AreEqual("Mine", sheet.Cell(3, 2).GetString());
        Assert.AreEqual(new DateTime(2026, 9, 1), sheet.Cell(4, 2).GetDateTime());
        Assert.AreEqual(new DateTime(2026, 9, 30), sheet.Cell(5, 2).GetDateTime());
        Assert.AreEqual(new DateTime(2026, 10, 1, 12, 0, 2), sheet.Cell(6, 2).GetDateTime());
        Assert.AreEqual("Status", sheet.Cell(8, 1).GetString());
        Assert.AreEqual("Count", sheet.Cell(8, 2).GetString());
        Assert.AreEqual("Amount", sheet.Cell(8, 3).GetString());
        Assert.AreEqual("Approved", sheet.Cell(11, 1).GetString());
        Assert.AreEqual(XLDataType.Number, sheet.Cell(11, 2).DataType);
        Assert.AreEqual(2, sheet.Cell(11, 2).GetValue<int>());
        Assert.AreEqual(150.00m, sheet.Cell(11, 3).GetValue<decimal>());
        Assert.AreEqual("Total", sheet.Cell(14, 1).GetString());
        Assert.AreEqual(3, sheet.Cell(14, 2).GetValue<int>());
        Assert.AreEqual(175.00m, sheet.Cell(14, 3).GetValue<decimal>());
    }

    /// <summary>An empty result still exports all five states and the total as numeric zeros.</summary>
    [TestMethod]
    public void EmptyResultExportsZeros()
    {
        var zeros = new List<ReportStatusTotal>
        {
            new("Draft", 0, 0m), new("Submitted", 0, 0m), new("Approved", 0, 0m), new("Rejected", 0, 0m), new("Paid", 0, 0m),
        };
        using var workbook = new XLWorkbook(new MemoryStream(ReportWorkbook.Create(Completed(zeros, 0, 0m))));
        IXLWorksheet sheet = workbook.Worksheet("Report");
        for (int row = 9; row <= 14; row++)
        {
            Assert.AreEqual(XLDataType.Number, sheet.Cell(row, 2).DataType);
            Assert.AreEqual(0, sheet.Cell(row, 2).GetValue<int>());
            Assert.AreEqual(0m, sheet.Cell(row, 3).GetValue<decimal>());
        }
    }

    /// <summary>The attachment name follows report-{id}.xlsx.</summary>
    [TestMethod]
    public void FileNameUsesTheIdentifier()
        => Assert.AreEqual($"report-{_id}.xlsx", ReportWorkbook.FileName(_id));

    /// <summary>A request without a persisted result cannot be exported.</summary>
    [TestMethod]
    public void MissingResultIsRejected()
    {
        ReportResponse pending = Completed(new List<ReportStatusTotal>(), 0, 0m) with { Result = null, Status = "Pending" };
        Assert.ThrowsExactly<InvalidOperationException>(() => ReportWorkbook.Create(pending));
    }

    private static ReportResponse Completed(IReadOnlyList<ReportStatusTotal> totals, int totalCount, decimal totalAmount)
    {
        var generated = new DateTime(2026, 10, 1, 12, 0, 2, DateTimeKind.Utc);
        return new ReportResponse(_id, "Mine", new DateOnly(2026, 9, 1), new DateOnly(2026, 9, 30), "Completed",
            generated, generated, generated, new ReportResult(generated, totalCount, totalAmount, totals), null);
    }
}
